	bodies.push(await request.text());
	if (bodies.length === 1) {
		await new Promise((_resolve, reject) => {
			request.signal.addEventListener('abort', () => {
				reject(new Error('aborted'));
			}, {once: true});
		});
	}

	return new Response('ok');
},

